from lib import *
S = SS('g24')
steps = [
    step("errors.Join(ErrA, ErrB):类型 *errors.joinError;Error() 是两个错误文字用换行连接(\"A 出错\\nB 出错\");errors.Is 对 ErrA、ErrB 都是 true,对 io.EOF 是 false;errors.Unwrap(j) 是 nil(Join 的 Unwrap 返回 []error,errors.Unwrap 只处理返回单个错误的 Unwrap),类型断言成 interface{ Unwrap() []error } 得到 2 个错误。nil 会被丢弃:errors.Join(nil, nil) 是 nil,errors.Join(nil, ErrA, nil).Error() 是 \"A 出错\";只有一个错误时 errors.Join(ErrA) 仍是 *errors.joinError(== ErrA 为 false,Is 为 true)。%v、%+v 都是 \"A 出错\\nB 出错\"。", t=tl(S(1)), done=lidx(S(1), 'errors.Join(ErrA, ErrB):类型', 'Error() =', 'errors.Is(j, ErrA)'), mark=lidx(S(1), 'errors.Unwrap(j)', 'errors.Join(nil, nil)', 'errors.Join(ErrA) 只有一个错误'), kv=KV([['Error()', '各个错误的文字用换行连接'], ['errors.Is / errors.As', '遍历所有子错误'], ['errors.Unwrap(j)', 'nil(要用 Unwrap() []error)'], ['nil 参数', '被丢弃;全是 nil 时返回 nil'], ['单个错误', '仍包成 *errors.joinError']], ['errors.Unwrap(j)'])),
    step("errors.As 在 Join 里按顺序深度优先、取第一个匹配:Join(&CodeErr{1}, 包装的 &CodeErr{2}, &CodeErr{3}) 取到 Code = 1;Join(包装的 &CodeErr{2}, &CodeErr{3}) 取到 Code = 2(先走完第一个分支)。嵌套 Join(Join(ErrA, io.EOF), ErrB):Is(io.EOF) 为 true,Error() 是 \"A 出错\\nEOF\\nB 出错\"。对比一个 Errorf 里两个 %w:类型 *fmt.wrapErrors,Error() 是 \"多个原因: A 出错; B 出错\",Is(ErrA) 与 Is(ErrB) 都是 true。", t=tl(S(2)), done=lidx(S(2), 'Code = 1', 'Code = 2', '嵌套 Join'), mark=lidx(S(2), 'fmt.Errorf("%w; %w")'), kv=KV([['errors.As', '深度优先,第一个匹配'], ['嵌套 Join', 'Is 能找到,Error() 把各层展平成多行'], ['Errorf 两个 %w', '*fmt.wrapErrors:自己拼文字,Is 同样能找到']], ['errors.As'])),
    step("典型用法:循环里依次打开 3 个文件,2 个失败,收集到 2 个错误,Join 之后是两行(第 0 个文件: open /no/a.txt: no such file or directory 与第 2 个文件: open /no/b.txt: no such file or directory);errors.Is(all, fs.ErrNotExist) 为 true;errors.Join() 没有参数返回 nil,errors.Join(errs[:0]...) 也是 nil——收集用的切片为空时不需要额外判断。", t=tl(S(3)), done=lidx(S(3), '收集到 2 个错误'), mark=lidx(S(3), 'errors.Is(all, fs.ErrNotExist)', 'errors.Join() 没有参数'), kv=KV([['收集错误', 'errs = append(errs, fmt.Errorf(\"第 %d 个文件: %w\", i, err))'], ['合并', 'errors.Join(errs...)'], ['空切片', '返回 nil,可以直接 return'], ['保留身份', 'errors.Is(all, fs.ErrNotExist) 仍为 true']], ['空切片'])),
    step("成本:errors.Join 2 个与 10 个错误都是 1 次分配;调用 Error() 分别是 4 次与 6 次分配(拼字符串);errors.Is(Join(ErrA, ErrB), ErrB) 17.44 ns/op;errors.Join(ErrA, ErrB) 14.54 ns/op。", t=tl(S(4)), done=lidx(S(4), 'errors.Join 2 个错误', 'errors.Join 10 个错误'), mark=lidx(S(4), 'errors.Is(Join', 'errors.Join(ErrA, ErrB)'), b=bars([['Join 2 个:分配', 1, '1'], ['Join 2 个的 Error():分配', 4, '4'], ['Join 10 个的 Error():分配', 6, '6']], 6, done=[0], mark=[1, 2]), kv=KV([['errors.Join', '1 次分配,14.54 ns(2 个错误)'], ['Error()', '分配 4 次(2 个)/ 6 次(10 个)'], ['errors.Is(Join(...), ErrB)', '17.44 ns/op']], ['Error()'])),
]
A = mkartg('g24', 24, 'Go,错误处理,errors.Join,errors.Is,errors.As,真实验证,动画演示',
    '在 Go 1.27.1 里验证 errors.Join:返回 *errors.joinError,Error() 用换行连接,Is 与 As 遍历所有子错误(As 深度优先取第一个匹配),errors.Unwrap 对它返回 nil,nil 参数被丢弃、全是 nil 时返回 nil;与同一个 Errorf 里的两个 %w 对比;循环里收集错误的写法;Join 本身 1 次分配,Error() 分配 4 到 6 次。',
    'errors.Join 把多个错误合成一个,常用在“收集所有失败而不是第一个失败”的场景。这篇用真实输出验证它的文字格式、Is 与 As 的查找顺序、与 Errorf 多个 %w 的区别、nil 的处理,以及成本。',
    [('换行', 'Join 的 Error() 用换行把各个错误的文字连起来'), ('深度优先', 'errors.As 在 Join 树里取到的是按顺序深度优先的第一个匹配'), ('1 次分配', 'errors.Join 本身的分配次数(无论 2 个还是 10 个)')],
    [('基本行为', '<p><code>Join</code> 丢掉 <code>nil</code>,全是 <code>nil</code> 时返回 <code>nil</code>(所以收集错误的切片为空时可以直接 <code>return errors.Join(errs...)</code>);只有一个错误也仍然包成 <code>*errors.joinError</code>,与原错误不相等,但 <code>errors.Is</code> 能找到。它的 <code>Unwrap</code> 返回 <code>[]error</code>,所以 <code>errors.Unwrap</code> 对它得到 <code>nil</code>——遍历要用 <code>Is</code>、<code>As</code>,或自己断言那个接口。</p>'),
     ('查找顺序', '<p><code>errors.As</code> 与 <code>errors.Is</code> 把 <code>Join</code> 与多个 <code>%w</code> 看成一棵树,先序深度优先:先把第一个子错误的整条分支走完再看第二个。因此 <code>As</code> 取到的是“按顺序最靠前的匹配”。<code>Errorf</code> 里的两个 <code>%w</code> 查找行为相同,区别只在文字格式:<code>Join</code> 是换行,<code>Errorf</code> 是你自己写的格式串。</p>'),
     ('收集错误', '<p>循环里把每次失败包装(带上下文,如文件序号)后追加到切片,最后 <code>errors.Join</code>,既保留了所有信息,<code>errors.Is</code> 也能判断“其中有没有某一类错误”。要注意多行的错误文字放进日志与响应时的格式——换行会让日志变成多行。</p>'),
     ('成本', '<p><code>Join</code> 自己只分配一次(保存子错误的切片,没有拷贝文字);真正分配多的是调用 <code>Error()</code> 拼字符串(4 到 6 次)。所以热路径上不要频繁 <code>Join</code> 之后又立刻 <code>Error()</code>。</p>')],
    steps,
    [ENV_G + '。所有输出来自同一个程序的真实运行;基准测试 7 轮取中位数;文件错误来自打开 /no/a.txt 与 /no/b.txt(不存在)',
     '没有验证:并发 goroutine 里收集错误的安全写法(见 errgroup 一篇)、Join 与 slog 等日志库的多行格式、错误数量很大时的内存占用、自定义 Unwrap() []error 类型在树里的遍历顺序以外的行为'],
    'errors.Join')
